(window.__quranSurahs=window.__quranSurahs||{})[53]={"nomPhon":"An-Najm","versets":{"1":{"text":"Par l'étoile à son déclin!","arabe":"وَٱلنَّجْمِ إِذَا هَوَىٰ"},"2":{"text":"Votre compagnon ne s'est pas égaré et n'a pas été induit en erreur","arabe":"مَا ضَلَّ صَاحِبُكُمْ وَمَا غَوَىٰ"},"3":{"text":"et il ne prononce rien sous l'effet de la passion;","arabe":"وَمَا يَنطِقُ عَنِ ٱلْهَوَىٰٓ"},"4":{"text":"ce n'est rien d'autre qu'une révélation inspirée.","arabe":"إِنْ هُوَ إِلَّا وَحْىٌۭ يُوحَىٰ"},"5":{"text":"Que lui a enseigné [l'Ange Gabriel] à la force prodigieuse,","arabe":"عَلَّمَهُۥ شَدِيدُ ٱلْقُوَىٰ"},"6":{"text":"doué de sagacité; c'est alors qu'il se montra sous sa forme réelle [angélique],","arabe":"ذُو مِرَّةٍۢ فَٱسْتَوَىٰ"},"7":{"text":"alors qu'il se trouvait à l'horizon supérieur.","arabe":"وَهُوَ بِٱلْأُفُقِ ٱلْأَعْلَىٰ"},"8":{"text":"Puis il se rapprocha et descendit encore plus bas,","arabe":"ثُمَّ دَنَا فَتَدَلَّىٰ"},"9":{"text":"et fut à deux portées d'arc, ou plus près encore.","arabe":"فَكَانَ قَابَ قَوْسَيْنِ أَوْ أَدْنَىٰ"},"10":{"text":"Il révéla à Son serviteur ce qu'Il révéla.","arabe":"فَأَوْحَىٰٓ إِلَىٰ عَبْدِهِۦ مَآ أَوْحَىٰ"},"11":{"text":"Le cœur n'a pas menti en ce qu'il a vu.","arabe":"مَا كَذَبَ ٱلْفُؤَادُ مَا رَأَىٰٓ"},"12":{"text":"Lui contestez-vous donc ce qu'il voit?","arabe":"أَفَتُمَٰرُونَهُۥ عَلَىٰ مَا يَرَىٰ"},"13":{"text":"Il l'a pourtant vu, lors d'une autre descente,","arabe":"وَلَقَدْ رَءَاهُ نَزْلَةً أُخْرَىٰ"},"14":{"text":"près de la Sidrat-ul-Muntahâ,","arabe":"عِندَ سِدْرَةِ ٱلْمُنتَهَىٰ"},"15":{"text":"près d'elle se trouve le jardin de Ma'w?:","arabe":"عِندَهَا جَنَّةُ ٱلْمَأْوَىٰٓ"},"16":{"text":"au moment où le lotus était couvert de ce qui le couvrait.","arabe":"إِذْ يَغْشَى ٱلسِّدْرَةَ مَا يَغْشَىٰ"},"17":{"text":"la vue n'a nullement dévié ni outrepassé la mesure.","arabe":"مَا زَاغَ ٱلْبَصَرُ وَمَا طَغَىٰ"},"18":{"text":"Il a bien vu certaines des grandes merveilles de son Seigneur.","arabe":"لَقَدْ رَأَىٰ مِنْ ءَايَٰتِ رَبِّهِ ٱلْكُبْرَىٰٓ"},"19":{"text":"Que vous en semble [des divinités], Lât et Uuzzâ","arabe":"أَفَرَءَيْتُمُ ٱللَّٰتَ وَٱلْعُزَّىٰ"},"20":{"text":"ainsi que Manât, cette troisième autre?","arabe":"وَمَنَوٰةَ ٱلثَّالِثَةَ ٱلْأُخْرَىٰٓ"},"21":{"text":"Sera-ce à vous le garçon et à Lui la fille?","arabe":"أَلَكُمُ ٱلذَّكَرُ وَلَهُ ٱلْأُنثَىٰ"},"22":{"text":"Que voilà donc un partage injuste!","arabe":"تِلْكَ إِذًۭا قِسْمَةٌۭ ضِيزَىٰٓ"},"23":{"text":"Ce ne sont que des noms que vous avez inventés, vous et vos ancêtres. Allah n'a fait descendre aucune preuve à leur sujet. Ils ne suivent que la conjecture et les passions de [leurs] âmes, alors que la guidée leur est venue de leur Seigneur.","arabe":"إِنْ هِىَ إِلَّآ أَسْمَآءٌۭ سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلْطَٰنٍ ۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَمَا تَهْوَى ٱلْأَنفُسُ ۖ وَلَقَدْ جَآءَهُم مِّن رَّبِّهِمُ ٱلْهُدَىٰٓ"},"24":{"text":"Ou bien l'homme aura-t-il tout ce qu'il désire?","arabe":"أَمْ لِلْإِنسَٰنِ مَا تَمَنَّىٰ"},"25":{"text":"A Allah appartiennent la vie future et la vie d'ici-bas.","arabe":"فَلِلَّهِ ٱلْءَاخِرَةُ وَٱلْأُولَىٰ"},"26":{"text":"Et que d'Anges dans les cieux dont l'intercession ne sert à rien, sinon qu'après qu'Allah l'aura permis, en faveur de qui Il veut et qu'Il agrée.","arabe":"۞ وَكَم مِّن مَّلَكٍۢ فِى ٱلسَّمَٰوَٰتِ لَا تُغْنِى شَفَٰعَتُهُمْ شَيْـًٔا إِلَّا مِنۢ بَعْدِ أَن يَأْذَنَ ٱللَّهُ لِمَن يَشَآءُ وَيَرْضَىٰٓ"},"27":{"text":"Ceux qui ne croient pas en l'au-delà donnent aux Anges des noms de femmes,","arabe":"إِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ لَيُسَمُّونَ ٱلْمَلَٰٓئِكَةَ تَسْمِيَةَ ٱلْأُنثَىٰ"},"28":{"text":"alors qu'ils n'en ont aucune science: ils ne suivent que la conjecture, alors que la conjecture ne sert à rien contre la vérité.","arabe":"وَمَا لَهُم بِهِۦ مِنْ عِلْمٍ ۖ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ ۖ وَإِنَّ ٱلظَّنَّ لَا يُغْنِى مِنَ ٱلْحَقِّ شَيْـًۭٔا"},"29":{"text":"Ecarte-toi donc, de celui qui tourne le dos à Notre rappel et qui ne désire que la vie présente.","arabe":"فَأَعْرِضْ عَن مَّن تَوَلَّىٰ عَن ذِكْرِنَا وَلَمْ يُرِدْ إِلَّا ٱلْحَيَوٰةَ ٱلدُّنْيَا"},"30":{"text":"Voilà toute la portée de leur savoir. Certes ton Seigneur connaît parfaitement celui qui s'égare de Son chemin et Il connaît parfaitement qui est bien guidé.","arabe":"ذَٰلِكَ مَبْلَغُهُم مِّنَ ٱلْعِلْمِ ۚ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعْلَمُ بِمَنِ ٱهْتَدَىٰ"},"31":{"text":"A Allah appartient ce qui est dans les cieux et sur la terre afin qu'Il rétribue ceux qui font le mal selon ce qu'ils œuvrent, et récompense ceux qui font le bien par la meilleure [récompense],","arabe":"وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ لِيَجْزِىَ ٱلَّذِينَ أَسَٰٓـُٔوا۟ بِمَا عَمِلُوا۟ وَيَجْزِىَ ٱلَّذِينَ أَحْسَنُوا۟ بِٱلْحُسْنَى"},"32":{"text":"ceux qui évitent les plus grands péchés ainsi que les turpitudes et [qui ne commettent] que des fautes légères. Certes, le pardon de Ton Seigneur est immense. C'est Lui qui vous connaît le mieux quand Il vous a produits de terre, et aussi quand vous étiez des embryons dans les ventres de vos mères. Ne vantez pas vous-mêmes votre pureté; c'est Lui qui connaît mieux ceux qui [Le] craignent.","arabe":"ٱلَّذِينَ يَجْتَنِبُونَ كَبَٰٓئِرَ ٱلْإِثْمِ وَٱلْفَوَٰحِشَ إِلَّا ٱللَّمَمَ ۚ إِنَّ رَبَّكَ وَٰسِعُ ٱلْمَغْفِرَةِ ۚ هُوَ أَعْلَمُ بِكُمْ إِذْ أَنشَأَكُم مِّنَ ٱلْأَرْضِ وَإِذْ أَنتُمْ أَجِنَّةٌۭ فِى بُطُونِ أُمَّهَٰتِكُمْ ۖ فَلَا تُزَكُّوٓا۟ أَنفُسَكُمْ ۖ هُوَ أَعْلَمُ بِمَنِ ٱتَّقَىٰٓ"},"33":{"text":"Vois-tu celui qui s'est détourné,","arabe":"أَفَرَءَيْتَ ٱلَّذِى تَوَلَّىٰ"},"34":{"text":"donné peu et a [finalement] cessé de donner?","arabe":"وَأَعْطَىٰ قَلِيلًۭا وَأَكْدَىٰٓ"},"35":{"text":"Détient-il la science de l'Inconnaissable en sorte qu'il voit?","arabe":"أَعِندَهُۥ عِلْمُ ٱلْغَيْبِ فَهُوَ يَرَىٰٓ"},"36":{"text":"Ne lui a-t-on pas annoncé ce qu'il y avait dans les feuilles de Moïse","arabe":"أَمْ لَمْ يُنَبَّأْ بِمَا فِى صُحُفِ مُوسَىٰ"},"37":{"text":"et celles d'Abraham qui a tenu parfaitement [sa promesse de transmettre]","arabe":"وَإِبْرَٰهِيمَ ٱلَّذِى وَفَّىٰٓ"},"38":{"text":"qu'aucune [âme] ne portera le fardeau (le péché) d'autrui,","arabe":"أَلَّا تَزِرُ وَازِرَةٌۭ وِزْرَ أُخْرَىٰ"},"39":{"text":"et qu'en vérité, l'homme n'obtient que [le fruit] de ses efforts;","arabe":"وَأَن لَّيْسَ لِلْإِنسَٰنِ إِلَّا مَا سَعَىٰ"},"40":{"text":"et que son effort, en vérité, lui sera présenté (le jour du Jugement).","arabe":"وَأَنَّ سَعْيَهُۥ سَوْفَ يُرَىٰ"},"41":{"text":"Ensuite il en sera récompensé pleinement,","arabe":"ثُمَّ يُجْزَىٰهُ ٱلْجَزَآءَ ٱلْأَوْفَىٰ"},"42":{"text":"et que tout aboutit, en vérité, vers ton Seigneur,","arabe":"وَأَنَّ إِلَىٰ رَبِّكَ ٱلْمُنتَهَىٰ"},"43":{"text":"et que c'est Lui qui a fait rire et qui a fait pleurer,","arabe":"وَأَنَّهُۥ هُوَ أَضْحَكَ وَأَبْكَىٰ"},"44":{"text":"et que c'est Lui qui a fait mourir et qui a ramené à la vie,","arabe":"وَأَنَّهُۥ هُوَ أَمَاتَ وَأَحْيَا"},"45":{"text":"et que c'est Lui qui a crée les deux éléments de couple, le mâle et la femelle,","arabe":"وَأَنَّهُۥ خَلَقَ ٱلزَّوْجَيْنِ ٱلذَّكَرَ وَٱلْأُنثَىٰ"},"46":{"text":"d'une goutte de sperme quand elle est éjaculée","arabe":"مِن نُّطْفَةٍ إِذَا تُمْنَىٰ"},"47":{"text":"et que la seconde création Lui incombe,","arabe":"وَأَنَّ عَلَيْهِ ٱلنَّشْأَةَ ٱلْأُخْرَىٰ"},"48":{"text":"et c'est Lui qui a enrichi et qui a fait acquérir.","arabe":"وَأَنَّهُۥ هُوَ أَغْنَىٰ وَأَقْنَىٰ"},"49":{"text":"Et c'est Lui qui est le Seigneur de Sirius,","arabe":"وَأَنَّهُۥ هُوَ رَبُّ ٱلشِّعْرَىٰ"},"50":{"text":"et c'est Lui qui a fait périr les anciens 'Aad,","arabe":"وَأَنَّهُۥٓ أَهْلَكَ عَادًا ٱلْأُولَىٰ"},"51":{"text":"ainsi que les Thamûd, et Il fit que rien n'en subsistât,","arabe":"وَثَمُودَا۟ فَمَآ أَبْقَىٰ"},"52":{"text":"ainsi que le peuple de Noé antérieurement, car ils étaient encore plus injustes et plus violents,","arabe":"وَقَوْمَ نُوحٍۢ مِّن قَبْلُ ۖ إِنَّهُمْ كَانُوا۟ هُمْ أَظْلَمَ وَأَطْغَىٰ"},"53":{"text":"de même qu'Il anéantit les villes renversées.","arabe":"وَٱلْمُؤْتَفِكَةَ أَهْوَىٰ"},"54":{"text":"Et les recouvrit de ce dont Il les recouvrit.","arabe":"فَغَشَّىٰهَا مَا غَشَّىٰ"},"55":{"text":"Lequel donc des bienfaits de ton Seigneur mets-tu en doute?","arabe":"فَبِأَىِّ ءَالَآءِ رَبِّكَ تَتَمَارَىٰ"},"56":{"text":"Voici un avertisseur analogue aux avertisseurs anciens:","arabe":"هَٰذَا نَذِيرٌۭ مِّنَ ٱلنُّذُرِ ٱلْأُولَىٰٓ"},"57":{"text":"l'Imminente (L'heure du Jugement) s'approche.","arabe":"أَزِفَتِ ٱلْءَازِفَةُ"},"58":{"text":"Rien d'autre en dehors d'Allah ne peut la dévoiler.","arabe":"لَيْسَ لَهَا مِن دُونِ ٱللَّهِ كَاشِفَةٌ"},"59":{"text":"Quoi! vous étonnez-vous de ce discours (le Coran)?","arabe":"أَفَمِنْ هَٰذَا ٱلْحَدِيثِ تَعْجَبُونَ"},"60":{"text":"Et vous [en] riez et n'[en] pleurez point?","arabe":"وَتَضْحَكُونَ وَلَا تَبْكُونَ"},"61":{"text":"absorbés [que vous êtes] par votre distraction.","arabe":"وَأَنتُمْ سَٰمِدُونَ"},"62":{"text":"Prosternez-vous donc à Allah et adorez-Le.","arabe":"فَٱسْجُدُوا۟ لِلَّهِ وَٱعْبُدُوا۟ ۩"}}};